-- mdastNode: {"data":{"codeFM":{"attrs":{"route":{"caption":"Home"}},"attrsText":"{ route: { caption: \"Home\" } }","cli":"sql index.sql","cmdLang":"sql","fromPresets":[{"codeFM":{"cli":"code PRESET --interpolate --injectable","cmdLang":"code","pi":{"args":["code","PRESET","--interpolate","--injectable"],"count":4,"flags":{"PRESET":true,"injectable":true,"interpolate":true},"pos":["PRESET","interpolate","injectable"],"posCount":3}},"meta":"sql * --interpolate --injectable"}],"lang":"sql","langSpec":{"comment":{"block":[{"close":"*/","nested":false,"open":"/*"}],"line":["--"]},"extensions":[".sql"],"id":"sql"},"meta":"index.sql { route: { caption: \"Home\" } }","pi":{"args":["sql","index.sql"],"count":2,"flags":{"PRESET":true,"index.sql":true,"injectable":true,"interpolate":true},"pos":["index.sql"],"posCount":1}}},"isBlob":false,"lang":"sql","language":"[Circular]","materializableIdentity":"index.sql","materializationArgs":{"deps":[],"graphs":[],"injectable":true,"injectedDep":[],"interpolate":true},"materializationAttrs":"[Circular]","meta":"index.sql { route: { caption: \"Home\" } }","nature":"MATERIALIZABLE","origin":{"data":"[Circular]","isActionableCodeCandidate":true,"isBlob":false,"lang":"sql","language":"[Circular]","materializableIdentity":"index.sql","materializationArgs":"[Circular]","materializationAttrs":"[Circular]","meta":"index.sql { route: { caption: \"Home\" } }","nature":"MATERIALIZABLE","position":{"end":{"column":4,"line":252,"offset":9696},"start":{"column":1,"line":229,"offset":8762}},"type":"code","value":"-- locals: ${Object.keys(__l).join(\", \")}\n-- mdastNode: ${safeJsonStringify(cell)}\nSET routes_json = sqlpage.read_file_as_text(''spry.d/auto/route/forest.auto.json'');\nSET root_path   = ''/scf'';\n\nSELECT ''card'' AS component, '''' AS title, 2 AS columns;\nSELECT\n  IFNULL(json_extract(c.value,''$.payloads[0].caption''),\n         json_extract(c.value,''$.basename''))                         AS title,\n  json_extract(c.value,''$.payloads[0].description'')                  AS description_md,\n  json_extract(c.value,''$.path'')                                     AS link\nFROM json_each(\n       json_extract(\n         (SELECT jt.value\n          FROM json_tree(json($routes_json)) AS jt\n          WHERE jt.type=''object''\n            AND json_extract(jt.value,''$.path'') = $root_path\n          LIMIT 1),\n         ''$.children''\n       )\n     ) AS c\nWHERE IFNULL(json_extract(c.value,''$.virtual''), 0) <> 1;"},"position":"[Circular]","provenance":{"file":{"data":{"edges":[{"from":{"contributeFM":{"cli":"include --base ../../../lib/universal","cmdLang":"include","fromPresets":[],"lang":"include","meta":"--base ../../../lib/universal","pi":{"args":["include","--base","../../../lib/universal"],"count":3,"flags":{"base":"../../../lib/universal"},"pos":["base"],"posCount":1}},"contributeQPI":{"bareWords":[],"cmdLang":"include","pi":"[Circular]"},"contributeSF":{"data":{"base":["../../../lib/universal"]},"success":true},"directive":"contribute","identity":"base","includables":[{"data":{"codeFM":{"cli":"sql sql.d/tail/schema-info.dml.sqlite.sql","cmdLang":"sql","fromPresets":["[Circular]"],"lang":"sql","langSpec":"[Circular]","meta":"sql.d/tail/schema-info.dml.sqlite.sql ","pi":{"args":["sql","sql.d/tail/schema-info.dml.sqlite.sql"],"count":2,"flags":{"PRESET":true,"injectable":true,"interpolate":true,"sql.d/tail/schema-info.dml.sqlite.sql":true},"pos":["sql.d/tail/schema-info.dml.sqlite.sql"],"posCount":1}}},"include":{"dest":{"kind":"prefix","value":"sql.d/tail"},"destPath":"sql.d/tail/schema-info.dml.sqlite.sql","destPrefix":"sql.d/tail","origin":{"candidate":"*.sql","destToken":"sql.d/tail","ir":{"cli":"sql *.sql sql.d/tail","cmdLang":"sql","pi":{"args":["sql","*.sql","sql.d/tail"],"count":3,"flags":{"*.sql":true,"sql.d/tail":true},"pos":["*.sql","sql.d/tail"],"posCount":2}},"label":"sql","lineNumInRawInstructions":1,"meta":"","parsedArgs":{"data":{"destToken":"sql.d/tail","label":"sql"},"success":true},"ppiq":{"bareWords":["*.sql","sql.d/tail"],"cmdLang":"sql","pi":"[Circular]"},"rawInstructions":"sql *.sql sql.d/tail"},"provenance":{"label":"*.sql","mimeType":"application/sql","path":"ABSOLUTE_PATH/lib/universal/schema-info.dml.sqlite.sql"},"strategy":{"encoding":"utf8-text","target":"local-fs"}},"isActionableCodeCandidate":true,"isBlob":false,"isContentAcquired":true,"lang":"sql","language":"[Circular]","materializableIdentity":"sql.d/tail/schema-info.dml.sqlite.sql","materializationArgs":{"deps":[],"graphs":[],"injectable":true,"injectedDep":[],"interpolate":true},"meta":"sql.d/tail/schema-info.dml.sqlite.sql ","nature":"MATERIALIZABLE","position":{"end":{"column":1,"line":176},"start":"[Circular]"},"type":"code","value":"-- @spry.nature sql @spry.sqlImpact dml\n\n-- Spry schema information is stored in sqlpage_files as a single-row-per-schema\n-- catalog with path ''spry.d/info-schema.auto.json'' (where ''main'' is schema).\n-- Stores a prettified JSON graph of the entire SQLite schema (tables, columns, \n-- indexes, foreign keys, views, triggers, and derived relations). These views \n-- project that JSON back into relational form for easy querying. Filter by \n-- schema_name in WHERE clauses (e.g., WHERE s.path = ''spry.d/info-schema.auto.json''). \n-- Requires SQLite JSON1.\n\n-- Populate with a comprehensive JSON graph of the current schema\nINSERT OR REPLACE INTO sqlpage_files (path, contents)\nVALUES (\n  ''spry.d/info-schema.auto.json'',\n  json_pretty(\n    json_object(\n      ''schema_name'', ''main'',\n      ''generated_on'', datetime(''now''),\n      ''sqlite_version'', sqlite_version(),\n\n      -- Attached databases\n      ''databases'',\n      (SELECT json_group_array(json_object(''seq'', seq, ''db_name'', name, ''db_file'', file))\n         FROM pragma_database_list),\n\n      -- Available collations\n      ''collations'',\n      (SELECT json_group_array(json_object(''seq'', seq, ''name'', name))\n         FROM pragma_collation_list),\n\n      -- Tables keyed by name, with nested columns, indexes, FKs, triggers\n      ''tables'',\n      (\n        SELECT json_group_object(\n                 tl.name,\n                 json_object(\n                   ''type'', tl.type,                 -- ''table''\n                   ''strict'', tl.strict,\n                   ''without_rowid'', 0,              -- not exposed by pragma_table_list; set 0 by default\n                   ''ncol'', tl.ncol,\n                   ''sql'', (SELECT s.sql FROM sqlite_schema AS s WHERE s.type=''table'' AND s.name=tl.name),\n\n                   ''columns'',\n                   (SELECT json_group_array(\n                             json_object(\n                               ''cid'', x.cid,\n                               ''name'', x.name,\n                               ''type'', x.type,\n                               ''notnull'', x.\"notnull\",\n                               ''dflt_value'', x.dflt_value,\n                               ''pk'', x.pk,\n                               ''hidden'', x.hidden\n                             )\n                           )\n                      FROM pragma_table_xinfo(tl.name) AS x),\n\n                   ''indexes'',\n                   (SELECT json_group_array(\n                             json_object(\n                               ''name'', il.name,\n                               ''origin'', il.origin,          -- ''c'',''u'',''pk''\n                               ''unique'', il.\"unique\",\n                               ''partial'', il.partial,\n                               ''where'',\n                                 (SELECT s.sql FROM sqlite_schema AS s\n                                   WHERE s.type=''index'' AND s.name=il.name),\n                               ''columns'',\n                                 (SELECT json_group_array(\n                                           json_object(\n                                             ''seqno'', ixi.seqno,\n                                             ''cid'', ixi.cid,\n                                             ''name'', ixi.name,\n                                             ''desc'', ixi.\"desc\",\n                                             ''coll'', ixi.coll,\n                                             ''key'', ixi.\"key\"\n                                           )\n                                         )\n                                    FROM pragma_index_xinfo(il.name) AS ixi)\n                             )\n                           )\n                      FROM pragma_index_list(tl.name) AS il),\n\n                   ''foreign_keys'',\n                   (SELECT json_group_array(\n                             json_object(\n                               ''id'', fk.id,\n                               ''seq'', fk.seq,\n                               ''from'', fk.\"from\",\n                               ''to'', fk.\"to\",\n                               ''table'', fk.\"table\",\n                               ''on_update'', fk.on_update,\n                               ''on_delete'', fk.on_delete,\n                               ''match'', fk.\"match\"\n                             )\n                           )\n                      FROM pragma_foreign_key_list(tl.name) AS fk),\n\n                   ''triggers'',\n                   (SELECT json_group_array(\n                             json_object(\n                               ''name'', t.name,\n                               ''sql'',  t.sql\n                             )\n                           )\n                      FROM sqlite_schema AS t\n                     WHERE t.type=''trigger'' AND t.tbl_name=tl.name)\n                 )\n               )\n          FROM pragma_table_list AS tl\n         WHERE tl.type=''table'' AND tl.name NOT LIKE ''sqlite_%''\n      ),\n\n      -- Views keyed by name\n      ''views'',\n      (\n        SELECT json_group_object(\n                 v.name,\n                 json_object(\n                   ''type'', ''view'',\n                   ''sql'',  v.sql,\n                   ''dependencies'', json(''[]'') -- placeholder (dependency parsing is non-trivial)\n                 )\n               )\n          FROM sqlite_schema AS v\n         WHERE v.type=''view'' AND v.name NOT LIKE ''sqlite_%''\n      ),\n\n      -- Virtual tables keyed by name (basic capture)\n      ''virtual_tables'',\n      (\n        SELECT json_group_object(\n                 tl.name,\n                 json_object(\n                   ''type'', tl.type,  -- ''virtual''\n                   ''sql'', (SELECT s.sql FROM sqlite_schema AS s WHERE s.type=''table'' AND s.name=tl.name)\n                 )\n               )\n          FROM pragma_table_list AS tl\n         WHERE tl.type=''virtual'' AND tl.name NOT LIKE ''sqlite_%''\n      ),\n\n      -- Triggers keyed by name (top-level convenience)\n      ''triggers'',\n      (\n        SELECT json_group_object(\n                 t.name,\n                 json_object(\n                   ''table'', t.tbl_name,\n                   ''sql'',   t.sql\n                 )\n               )\n          FROM sqlite_schema AS t\n         WHERE t.type=''trigger'' AND t.name NOT LIKE ''sqlite_%''\n      ),\n\n      -- Relations derived from all foreign keys\n      ''relations'',\n      (\n        SELECT json_group_array(\n                 json_object(\n                   ''name'', printf(''%s_%s_%s_%s'', fk.tbl_name, fk.\"from\", fk.\"table\", fk.\"to\"),\n                   ''from_table'', fk.tbl_name,\n                   ''from_columns'', json_array(fk.\"from\"),\n                   ''to_table'', fk.\"table\",\n                   ''to_columns'', json_array(fk.\"to\"),\n                   ''type'', ''many_to_one'',\n                   ''on_update'', fk.on_update,\n                   ''on_delete'', fk.on_delete,\n                   ''match'', fk.\"match\"\n                 )\n               )\n          FROM (\n                 SELECT\n                   tbl.name AS tbl_name,\n                   fk.\"from\",\n                   fk.\"to\",\n                   fk.\"table\",\n                   fk.on_update,\n                   fk.on_delete,\n                   fk.\"match\"\n                 FROM sqlite_schema AS tbl,\n                      pragma_foreign_key_list(tbl.name) AS fk\n                 WHERE tbl.type=''table'' AND tbl.name NOT LIKE ''sqlite_%''\n               ) AS fk\n      )\n    )\n  )\n);\n\n-- Tables (one row per table)\nDROP VIEW IF EXISTS spry_schema_info_table;\nCREATE VIEW IF NOT EXISTS spry_schema_info_table AS\nSELECT\n  ''main''                                    AS schema_name,\n  t.key                                     AS table_name,\n  json_extract(t.value,''$.type'')            AS type,\n  json_extract(t.value,''$.ncol'')            AS ncol,\n  json_extract(t.value,''$.strict'')          AS strict,\n  json_extract(t.value,''$.without_rowid'')   AS without_rowid,\n  json_extract(t.value,''$.sql'')             AS definition_sql\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.tables'') AS t\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Table columns (one row per column per table)\nDROP VIEW IF EXISTS spry_schema_info_table_column;\nCREATE VIEW IF NOT EXISTS spry_schema_info_table_column AS\nSELECT\n  ''main''                                        AS schema_name,\n  t.key                                         AS table_name,\n  json_extract(c.value,''$.cid'')                 AS cid,\n  json_extract(c.value,''$.name'')                AS column_name,\n  json_extract(c.value,''$.type'')                AS column_type,\n  json_extract(c.value,''$.notnull'')             AS not_null,\n  json_extract(c.value,''$.dflt_value'')          AS dflt_value,\n  json_extract(c.value,''$.pk'')                  AS part_of_pk,\n  json_extract(c.value,''$.hidden'')              AS hidden\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.tables'') AS t,\n     json_each(t.value, ''$.columns'')           AS c\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Views (one row per view)\nDROP VIEW IF EXISTS spry_schema_info_view;\nCREATE VIEW IF NOT EXISTS spry_schema_info_view AS\nSELECT\n  ''main''                           AS schema_name,\n  v.key                            AS view_name,\n  json_extract(v.value,''$.type'')   AS type,\n  json_extract(v.value,''$.sql'')    AS definition_sql\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.views'') AS v\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- View columns (if your schema_graph_json includes a $.views[*].columns array)\nDROP VIEW IF EXISTS spry_schema_info_view_column;\nCREATE VIEW IF NOT EXISTS spry_schema_info_view_column AS\nSELECT\n  ''main''                          AS schema_name,\n  v.key                           AS view_name,\n  json_extract(vc.value,''$.cid'')  AS cid,\n  json_extract(vc.value,''$.name'') AS column_name,\n  json_extract(vc.value,''$.type'') AS column_type,\n  json_extract(vc.value,''$.notnull'') AS not_null,\n  json_extract(vc.value,''$.dflt_value'') AS dflt_value\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.views'') AS v\nLEFT JOIN json_each(v.value, ''$.columns'') AS vc ON 1=1\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Indexes (one row per index per table)\nDROP VIEW IF EXISTS spry_schema_info_index;\nCREATE VIEW IF NOT EXISTS spry_schema_info_index AS\nSELECT\n  ''main''                                       AS schema_name,\n  t.key                                        AS table_name,\n  json_extract(i.value,''$.name'')               AS index_name,\n  json_extract(i.value,''$.origin'')             AS origin,      -- ''c'',''u'',''pk''\n  json_extract(i.value,''$.unique'')             AS is_unique,\n  json_extract(i.value,''$.partial'')            AS is_partial,\n  json_extract(i.value,''$.where'')              AS definition_sql\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.tables'')         AS t,\n     json_each(t.value, ''$.indexes'')           AS i\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Index columns (one row per column per index)\nDROP VIEW IF EXISTS spry_schema_info_index_column;\nCREATE VIEW IF NOT EXISTS spry_schema_info_index_column AS\nSELECT\n  ''main''                                        AS schema_name,\n  t.key                                         AS table_name,\n  json_extract(i.value,''$.name'')                AS index_name,\n  json_extract(ic.value,''$.seqno'')              AS seqno,\n  json_extract(ic.value,''$.cid'')                AS cid,\n  json_extract(ic.value,''$.name'')               AS column_name,\n  json_extract(ic.value,''$.desc'')               AS is_desc,\n  json_extract(ic.value,''$.coll'')               AS collation_name,\n  json_extract(ic.value,''$.key'')                AS is_key_column\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.tables'')          AS t,\n     json_each(t.value, ''$.indexes'')            AS i,\n     json_each(i.value, ''$.columns'')            AS ic\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Foreign keys (one row per referencing column)\nDROP VIEW IF EXISTS spry_schema_info_foreign_key;\nCREATE VIEW IF NOT EXISTS spry_schema_info_foreign_key AS\nSELECT\n  ''main''                                   AS schema_name,\n  t.key                                    AS table_name,\n  json_extract(fk.value,''$.id'')            AS fk_id,\n  json_extract(fk.value,''$.seq'')           AS seq,\n  json_extract(fk.value,''$.from'')          AS from_column,\n  json_extract(fk.value,''$.to'')            AS to_column,\n  json_extract(fk.value,''$.table'')         AS ref_table,\n  json_extract(fk.value,''$.on_update'')     AS on_update,\n  json_extract(fk.value,''$.on_delete'')     AS on_delete,\n  json_extract(fk.value,''$.match'')         AS match\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.tables'')     AS t,\n     json_each(t.value, ''$.foreign_keys'')  AS fk\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Table triggers (one row per trigger per table)\nDROP VIEW IF EXISTS spry_schema_info_table_trigger;\nCREATE VIEW IF NOT EXISTS spry_schema_info_table_trigger AS\nSELECT\n  ''main''                                AS schema_name,\n  t.key                                 AS table_name,\n  json_extract(tr.value,''$.name'')       AS trigger_name,\n  json_extract(tr.value,''$.sql'')        AS definition_sql\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.tables'')  AS t,\n     json_each(t.value, ''$.triggers'')   AS tr\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Top-level triggers (if captured under $.triggers object)\nDROP VIEW IF EXISTS spry_schema_info_trigger;\nCREATE VIEW IF NOT EXISTS spry_schema_info_trigger AS\nSELECT\n  ''main''                                AS schema_name,\n  trg.key                               AS trigger_name,\n  json_extract(trg.value,''$.table'')     AS table_name,\n  json_extract(trg.value,''$.sql'')       AS definition_sql\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.triggers'') AS trg\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Relations derived in schema_graph_json (one row per relation)\nDROP VIEW IF EXISTS spry_schema_info_relation;\nCREATE VIEW IF NOT EXISTS spry_schema_info_relation AS\nSELECT\n  ''main''                                  AS schema_name,\n  json_extract(r.value,''$.name'')          AS relation_name,\n  json_extract(r.value,''$.from_table'')    AS from_table,\n  json_extract(r.value,''$.to_table'')      AS to_table,\n  json_extract(r.value,''$.type'')          AS relation_type,\n  json_extract(r.value,''$.on_update'')     AS on_update,\n  json_extract(r.value,''$.on_delete'')     AS on_delete,\n  json_extract(r.value,''$.match'')         AS match,\n  json_extract(r.value,''$.from_columns'')  AS from_columns_json,\n  json_extract(r.value,''$.to_columns'')    AS to_columns_json\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.relations'') AS r\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n"},{"data":{"codeFM":{"cli":"sql sql.d/tail/0000.sql","cmdLang":"sql","fromPresets":["[Circular]"],"lang":"sql","langSpec":"[Circular]","meta":"sql.d/tail/0000.sql ","pi":{"args":["sql","sql.d/tail/0000.sql"],"count":2,"flags":{"PRESET":true,"injectable":true,"interpolate":true,"sql.d/tail/0000.sql":true},"pos":["sql.d/tail/0000.sql"],"posCount":1}}},"include":{"dest":{"kind":"path","value":"sql.d/tail/0000.sql"},"destPath":"sql.d/tail/0000.sql","origin":{"candidate":"schema-info.dml.sqlite.sql","destToken":"sql.d/tail/0000.sql","ir":{"cli":"sql schema-info.dml.sqlite.sql sql.d/tail/0000.sql","cmdLang":"sql","pi":{"args":["sql","schema-info.dml.sqlite.sql","sql.d/tail/0000.sql"],"count":3,"flags":{"schema-info.dml.sqlite.sql":true,"sql.d/tail/0000.sql":true},"pos":["schema-info.dml.sqlite.sql","sql.d/tail/0000.sql"],"posCount":2}},"label":"sql","lineNumInRawInstructions":2,"meta":"","parsedArgs":{"data":{"destToken":"sql.d/tail/0000.sql","label":"sql"},"success":true},"ppiq":{"bareWords":["schema-info.dml.sqlite.sql","sql.d/tail/0000.sql"],"cmdLang":"sql","pi":"[Circular]"},"rawInstructions":"sql schema-info.dml.sqlite.sql sql.d/tail/0000.sql"},"provenance":{"label":"schema-info.dml.sqlite.sql","mimeType":"application/sql","path":"ABSOLUTE_PATH/lib/universal/schema-info.dml.sqlite.sql"},"strategy":{"encoding":"utf8-text","target":"local-fs"}},"isActionableCodeCandidate":true,"isBlob":false,"isContentAcquired":true,"lang":"sql","language":"[Circular]","materializableIdentity":"sql.d/tail/0000.sql","materializationArgs":{"deps":[],"graphs":[],"injectable":true,"injectedDep":[],"interpolate":true},"meta":"sql.d/tail/0000.sql ","nature":"MATERIALIZABLE","position":{"end":{"column":1,"line":177},"start":"[Circular]"},"type":"code","value":"-- @spry.nature sql @spry.sqlImpact dml\n\n-- Spry schema information is stored in sqlpage_files as a single-row-per-schema\n-- catalog with path ''spry.d/info-schema.auto.json'' (where ''main'' is schema).\n-- Stores a prettified JSON graph of the entire SQLite schema (tables, columns, \n-- indexes, foreign keys, views, triggers, and derived relations). These views \n-- project that JSON back into relational form for easy querying. Filter by \n-- schema_name in WHERE clauses (e.g., WHERE s.path = ''spry.d/info-schema.auto.json''). \n-- Requires SQLite JSON1.\n\n-- Populate with a comprehensive JSON graph of the current schema\nINSERT OR REPLACE INTO sqlpage_files (path, contents)\nVALUES (\n  ''spry.d/info-schema.auto.json'',\n  json_pretty(\n    json_object(\n      ''schema_name'', ''main'',\n      ''generated_on'', datetime(''now''),\n      ''sqlite_version'', sqlite_version(),\n\n      -- Attached databases\n      ''databases'',\n      (SELECT json_group_array(json_object(''seq'', seq, ''db_name'', name, ''db_file'', file))\n         FROM pragma_database_list),\n\n      -- Available collations\n      ''collations'',\n      (SELECT json_group_array(json_object(''seq'', seq, ''name'', name))\n         FROM pragma_collation_list),\n\n      -- Tables keyed by name, with nested columns, indexes, FKs, triggers\n      ''tables'',\n      (\n        SELECT json_group_object(\n                 tl.name,\n                 json_object(\n                   ''type'', tl.type,                 -- ''table''\n                   ''strict'', tl.strict,\n                   ''without_rowid'', 0,              -- not exposed by pragma_table_list; set 0 by default\n                   ''ncol'', tl.ncol,\n                   ''sql'', (SELECT s.sql FROM sqlite_schema AS s WHERE s.type=''table'' AND s.name=tl.name),\n\n                   ''columns'',\n                   (SELECT json_group_array(\n                             json_object(\n                               ''cid'', x.cid,\n                               ''name'', x.name,\n                               ''type'', x.type,\n                               ''notnull'', x.\"notnull\",\n                               ''dflt_value'', x.dflt_value,\n                               ''pk'', x.pk,\n                               ''hidden'', x.hidden\n                             )\n                           )\n                      FROM pragma_table_xinfo(tl.name) AS x),\n\n                   ''indexes'',\n                   (SELECT json_group_array(\n                             json_object(\n                               ''name'', il.name,\n                               ''origin'', il.origin,          -- ''c'',''u'',''pk''\n                               ''unique'', il.\"unique\",\n                               ''partial'', il.partial,\n                               ''where'',\n                                 (SELECT s.sql FROM sqlite_schema AS s\n                                   WHERE s.type=''index'' AND s.name=il.name),\n                               ''columns'',\n                                 (SELECT json_group_array(\n                                           json_object(\n                                             ''seqno'', ixi.seqno,\n                                             ''cid'', ixi.cid,\n                                             ''name'', ixi.name,\n                                             ''desc'', ixi.\"desc\",\n                                             ''coll'', ixi.coll,\n                                             ''key'', ixi.\"key\"\n                                           )\n                                         )\n                                    FROM pragma_index_xinfo(il.name) AS ixi)\n                             )\n                           )\n                      FROM pragma_index_list(tl.name) AS il),\n\n                   ''foreign_keys'',\n                   (SELECT json_group_array(\n                             json_object(\n                               ''id'', fk.id,\n                               ''seq'', fk.seq,\n                               ''from'', fk.\"from\",\n                               ''to'', fk.\"to\",\n                               ''table'', fk.\"table\",\n                               ''on_update'', fk.on_update,\n                               ''on_delete'', fk.on_delete,\n                               ''match'', fk.\"match\"\n                             )\n                           )\n                      FROM pragma_foreign_key_list(tl.name) AS fk),\n\n                   ''triggers'',\n                   (SELECT json_group_array(\n                             json_object(\n                               ''name'', t.name,\n                               ''sql'',  t.sql\n                             )\n                           )\n                      FROM sqlite_schema AS t\n                     WHERE t.type=''trigger'' AND t.tbl_name=tl.name)\n                 )\n               )\n          FROM pragma_table_list AS tl\n         WHERE tl.type=''table'' AND tl.name NOT LIKE ''sqlite_%''\n      ),\n\n      -- Views keyed by name\n      ''views'',\n      (\n        SELECT json_group_object(\n                 v.name,\n                 json_object(\n                   ''type'', ''view'',\n                   ''sql'',  v.sql,\n                   ''dependencies'', json(''[]'') -- placeholder (dependency parsing is non-trivial)\n                 )\n               )\n          FROM sqlite_schema AS v\n         WHERE v.type=''view'' AND v.name NOT LIKE ''sqlite_%''\n      ),\n\n      -- Virtual tables keyed by name (basic capture)\n      ''virtual_tables'',\n      (\n        SELECT json_group_object(\n                 tl.name,\n                 json_object(\n                   ''type'', tl.type,  -- ''virtual''\n                   ''sql'', (SELECT s.sql FROM sqlite_schema AS s WHERE s.type=''table'' AND s.name=tl.name)\n                 )\n               )\n          FROM pragma_table_list AS tl\n         WHERE tl.type=''virtual'' AND tl.name NOT LIKE ''sqlite_%''\n      ),\n\n      -- Triggers keyed by name (top-level convenience)\n      ''triggers'',\n      (\n        SELECT json_group_object(\n                 t.name,\n                 json_object(\n                   ''table'', t.tbl_name,\n                   ''sql'',   t.sql\n                 )\n               )\n          FROM sqlite_schema AS t\n         WHERE t.type=''trigger'' AND t.name NOT LIKE ''sqlite_%''\n      ),\n\n      -- Relations derived from all foreign keys\n      ''relations'',\n      (\n        SELECT json_group_array(\n                 json_object(\n                   ''name'', printf(''%s_%s_%s_%s'', fk.tbl_name, fk.\"from\", fk.\"table\", fk.\"to\"),\n                   ''from_table'', fk.tbl_name,\n                   ''from_columns'', json_array(fk.\"from\"),\n                   ''to_table'', fk.\"table\",\n                   ''to_columns'', json_array(fk.\"to\"),\n                   ''type'', ''many_to_one'',\n                   ''on_update'', fk.on_update,\n                   ''on_delete'', fk.on_delete,\n                   ''match'', fk.\"match\"\n                 )\n               )\n          FROM (\n                 SELECT\n                   tbl.name AS tbl_name,\n                   fk.\"from\",\n                   fk.\"to\",\n                   fk.\"table\",\n                   fk.on_update,\n                   fk.on_delete,\n                   fk.\"match\"\n                 FROM sqlite_schema AS tbl,\n                      pragma_foreign_key_list(tbl.name) AS fk\n                 WHERE tbl.type=''table'' AND tbl.name NOT LIKE ''sqlite_%''\n               ) AS fk\n      )\n    )\n  )\n);\n\n-- Tables (one row per table)\nDROP VIEW IF EXISTS spry_schema_info_table;\nCREATE VIEW IF NOT EXISTS spry_schema_info_table AS\nSELECT\n  ''main''                                    AS schema_name,\n  t.key                                     AS table_name,\n  json_extract(t.value,''$.type'')            AS type,\n  json_extract(t.value,''$.ncol'')            AS ncol,\n  json_extract(t.value,''$.strict'')          AS strict,\n  json_extract(t.value,''$.without_rowid'')   AS without_rowid,\n  json_extract(t.value,''$.sql'')             AS definition_sql\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.tables'') AS t\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Table columns (one row per column per table)\nDROP VIEW IF EXISTS spry_schema_info_table_column;\nCREATE VIEW IF NOT EXISTS spry_schema_info_table_column AS\nSELECT\n  ''main''                                        AS schema_name,\n  t.key                                         AS table_name,\n  json_extract(c.value,''$.cid'')                 AS cid,\n  json_extract(c.value,''$.name'')                AS column_name,\n  json_extract(c.value,''$.type'')                AS column_type,\n  json_extract(c.value,''$.notnull'')             AS not_null,\n  json_extract(c.value,''$.dflt_value'')          AS dflt_value,\n  json_extract(c.value,''$.pk'')                  AS part_of_pk,\n  json_extract(c.value,''$.hidden'')              AS hidden\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.tables'') AS t,\n     json_each(t.value, ''$.columns'')           AS c\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Views (one row per view)\nDROP VIEW IF EXISTS spry_schema_info_view;\nCREATE VIEW IF NOT EXISTS spry_schema_info_view AS\nSELECT\n  ''main''                           AS schema_name,\n  v.key                            AS view_name,\n  json_extract(v.value,''$.type'')   AS type,\n  json_extract(v.value,''$.sql'')    AS definition_sql\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.views'') AS v\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- View columns (if your schema_graph_json includes a $.views[*].columns array)\nDROP VIEW IF EXISTS spry_schema_info_view_column;\nCREATE VIEW IF NOT EXISTS spry_schema_info_view_column AS\nSELECT\n  ''main''                          AS schema_name,\n  v.key                           AS view_name,\n  json_extract(vc.value,''$.cid'')  AS cid,\n  json_extract(vc.value,''$.name'') AS column_name,\n  json_extract(vc.value,''$.type'') AS column_type,\n  json_extract(vc.value,''$.notnull'') AS not_null,\n  json_extract(vc.value,''$.dflt_value'') AS dflt_value\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.views'') AS v\nLEFT JOIN json_each(v.value, ''$.columns'') AS vc ON 1=1\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Indexes (one row per index per table)\nDROP VIEW IF EXISTS spry_schema_info_index;\nCREATE VIEW IF NOT EXISTS spry_schema_info_index AS\nSELECT\n  ''main''                                       AS schema_name,\n  t.key                                        AS table_name,\n  json_extract(i.value,''$.name'')               AS index_name,\n  json_extract(i.value,''$.origin'')             AS origin,      -- ''c'',''u'',''pk''\n  json_extract(i.value,''$.unique'')             AS is_unique,\n  json_extract(i.value,''$.partial'')            AS is_partial,\n  json_extract(i.value,''$.where'')              AS definition_sql\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.tables'')         AS t,\n     json_each(t.value, ''$.indexes'')           AS i\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Index columns (one row per column per index)\nDROP VIEW IF EXISTS spry_schema_info_index_column;\nCREATE VIEW IF NOT EXISTS spry_schema_info_index_column AS\nSELECT\n  ''main''                                        AS schema_name,\n  t.key                                         AS table_name,\n  json_extract(i.value,''$.name'')                AS index_name,\n  json_extract(ic.value,''$.seqno'')              AS seqno,\n  json_extract(ic.value,''$.cid'')                AS cid,\n  json_extract(ic.value,''$.name'')               AS column_name,\n  json_extract(ic.value,''$.desc'')               AS is_desc,\n  json_extract(ic.value,''$.coll'')               AS collation_name,\n  json_extract(ic.value,''$.key'')                AS is_key_column\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.tables'')          AS t,\n     json_each(t.value, ''$.indexes'')            AS i,\n     json_each(i.value, ''$.columns'')            AS ic\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Foreign keys (one row per referencing column)\nDROP VIEW IF EXISTS spry_schema_info_foreign_key;\nCREATE VIEW IF NOT EXISTS spry_schema_info_foreign_key AS\nSELECT\n  ''main''                                   AS schema_name,\n  t.key                                    AS table_name,\n  json_extract(fk.value,''$.id'')            AS fk_id,\n  json_extract(fk.value,''$.seq'')           AS seq,\n  json_extract(fk.value,''$.from'')          AS from_column,\n  json_extract(fk.value,''$.to'')            AS to_column,\n  json_extract(fk.value,''$.table'')         AS ref_table,\n  json_extract(fk.value,''$.on_update'')     AS on_update,\n  json_extract(fk.value,''$.on_delete'')     AS on_delete,\n  json_extract(fk.value,''$.match'')         AS match\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.tables'')     AS t,\n     json_each(t.value, ''$.foreign_keys'')  AS fk\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Table triggers (one row per trigger per table)\nDROP VIEW IF EXISTS spry_schema_info_table_trigger;\nCREATE VIEW IF NOT EXISTS spry_schema_info_table_trigger AS\nSELECT\n  ''main''                                AS schema_name,\n  t.key                                 AS table_name,\n  json_extract(tr.value,''$.name'')       AS trigger_name,\n  json_extract(tr.value,''$.sql'')        AS definition_sql\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.tables'')  AS t,\n     json_each(t.value, ''$.triggers'')   AS tr\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Top-level triggers (if captured under $.triggers object)\nDROP VIEW IF EXISTS spry_schema_info_trigger;\nCREATE VIEW IF NOT EXISTS spry_schema_info_trigger AS\nSELECT\n  ''main''                                AS schema_name,\n  trg.key                               AS trigger_name,\n  json_extract(trg.value,''$.table'')     AS table_name,\n  json_extract(trg.value,''$.sql'')       AS definition_sql\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.triggers'') AS trg\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n\n-- Relations derived in schema_graph_json (one row per relation)\nDROP VIEW IF EXISTS spry_schema_info_relation;\nCREATE VIEW IF NOT EXISTS spry_schema_info_relation AS\nSELECT\n  ''main''                                  AS schema_name,\n  json_extract(r.value,''$.name'')          AS relation_name,\n  json_extract(r.value,''$.from_table'')    AS from_table,\n  json_extract(r.value,''$.to_table'')      AS to_table,\n  json_extract(r.value,''$.type'')          AS relation_type,\n  json_extract(r.value,''$.on_update'')     AS on_update,\n  json_extract(r.value,''$.on_delete'')     AS on_delete,\n  json_extract(r.value,''$.match'')         AS match,\n  json_extract(r.value,''$.from_columns'')  AS from_columns_json,\n  json_extract(r.value,''$.to_columns'')    AS to_columns_json\nFROM sqlpage_files AS s,\n     json_each(s.contents, ''$.relations'') AS r\nWHERE s.path = ''spry.d/info-schema.auto.json'';\n"}],"instructions":"[Circular]","isCodeDirectiveCandidate":true,"lang":"include","meta":"--base ../../../lib/universal","position":{"end":{"column":4,"line":178,"offset":6842},"start":{"column":1,"line":175,"offset":6726}},"type":"code","value":"sql *.sql sql.d/tail\nsql schema-info.dml.sqlite.sql sql.d/tail/0000.sql"},"rel":"isIncludedNode","to":"[Circular]"},{"from":"[Circular]","rel":"isIncludedNode","to":"[Circular]"}],"frontmatter":{"sqlpage-conf":{"allow_exec":true,"database_url":"${env.SPRY_DB}","port":"${env.PORT}","web_root":"./dev-src.auto"}},"provenance":{"label":"Spryfile.md","mimeType":"text/markdown","path":"Spryfile.md"}},"history":["Spryfile.md"],"messages":[],"value":"---\nsqlpage-conf:\n  database_url: ${env.SPRY_DB}\n  web_root: \"./dev-src.auto\"\n  allow_exec: true\n  port: ${env.PORT}\n---\n\n# Secure Controls Framework (SCF) SQLPage Application\n\nThis script automates the conversion of the latest Secure Controls Framework\n(SCF) Excel workbook from the\n[official SCF GitHub repository](https://github.com/securecontrolsframework/securecontrolsframework)\ninto a structured SQLite database.\n\n- Uses Spry to manage tasks and generate the SQLPage presentation layer.\n- Uses DuckDB with its built-in `excel` and `sqlite` extensions.\n\n## Spry Axiom configuration\n\n`code DEFAULTS` is a special directive use by Spry''s Axiom library to supply\ndefault flags to specific code blocks like `sql`, `text`, etc. allowing them to\nbe interpolatable (`${...}`) and injectable (using `PARTIAL`s) by default\ninstead of having to pass `--interpolate` and `--injectable` into each code\ncell. 💡 `code DEFAULTS` is necessary in Spry SQLPage playbooks to tell Axiom\nhow to treat `sql` code fenced blocks.\n\n```code DEFAULTS\nsql * --interpolate --injectable\n```\n\nThe following example shows how arbitrary files can be \"contributed\" to\n`sqlpage_files`. `--base` should be relative to the current working directory\n(CWD). 💡 It''s included just as an examplar and is not required:\n\n```contribute sqlpage_files --base ../../../lib/axiom/fixture/sundry\n**/* SUNDRY\n```\n\nThe following example shows how template files can be \"contributed\" to\n`sqlpage_files` but only when `--package` is being used. Spry picks them up from\n`../sqlpage/templates/*` and store them in `templates/*` path in `sqlpage_files`\ntable only during `--package` operation:\n\n```contribute sqlpage_files --base sqlpage/templates --mode package\n**/* templates --mime text/plain\n```\n\n💡 You should use the above technique if you ever create custom\n`sqlplage/templates` files that you want included in the database.\n\n## Setup\n\nDownload the SCF Excel workbook from the GitHub repo and place it into the same\ndirectory as this `README.md` and then run `spry.ts task prepare-db`. We supply\nour own `#!/usr/bin/env -S bash` shebang since we have comments in the shell\nscript.\n\n```bash prepare-db --descr \"Delete and recreate the SQLite database used by SQLPage\"\n#!/usr/bin/env -S bash\nrm -f scf-2025.3.sqlite.db                  # will be re-created by DuckDB `ATTACH`\ncat prepare.duckdb.sql | duckdb \":memory:\"  # DuckDB processes in memory but creates SQLite DB\n```\n\n## Environment variables and .envrc\n\nThis project reads configuration from environment variables. Two variables you\nwill commonly set in development are:\n\n- `SPRY_DB` — the database connection URL used by SQLPage and Spry. Example\n  value used here: `sqlite://scf-2025.3.sqlite.db?mode=rwc`\n  - Scheme: `sqlite://` followed by a path (relative or absolute) to the SQLite\n    file.\n  - Query `mode=rwc` tells SQLite/DuckDB to open the file for read/write and\n    create it if missing.\n  - If you prefer a path under a `data/` directory, set e.g.\n    `sqlite://./data/scf-2025.3.sqlite.db?mode=rwc`.\n\n- `PORT` — the TCP port the local SQLPage server or other local web component\n  should listen on (example: `9227`).\n\nRecommended practice is to keep these values in a local, directory-scoped\nenvironment file. If you use direnv (recommended), create a file named `.envrc`\nin this directory.\n\nPOSIX-style example (bash/zsh):\n\n```envrc prepare-env -C ./.envrc -X --gitignore --descr \"Generate .envrc file and add it to local .gitignore if it''s not already there\"\nexport SPRY_DB=\"sqlite://scf-2025.3.sqlite.db?mode=rwc\"\nexport PORT=9227\n```\n\nThen run `direnv allow` in this project directory to load the `.envrc` into your\nshell environment. direnv will evaluate `.envrc` only after you explicitly allow\nit.\n\n## Security and repository hygiene\n\n- Never commit secrets or production credentials into `.envrc`. Treat `.envrc`\n  like a local-only file.\n- Add `.envrc` to your local `.gitignore` if you keep secrets there.\n  Alternatively commit a `.envrc.example` or `.envrc.sample` with safe,\n  non-secret defaults to document expected variables.\n- The SQLite file (e.g. `scf-2025.3.sqlite.db`) is a binary database file — you\n  will usually not check this into version control. Add that filename or the\n  `data/` directory to `.gitignore` as well.\n\nWhy these variables matter here\n\n- The YAML header at the top of this `Spryfile.md` reads\n  `database_url: ${env.SPRY_DB}` and `port: ${env.PORT}` — Spry and the SQLPage\n  tooling will substitute those environment values when building or serving the\n  site.\n- If `SPRY_DB` is not set, the tooling may fail to find the database or fall\n  back to defaults; explicitly setting it ensures predictable, repeatable dev\n  runs.\n\nQuick troubleshooting\n\n- If the server does not start on the expected port, verify `echo $PORT` (or\n  `echo $SPRY_DB`) in your shell to confirm values are loaded.\n- If direnv appears not to load `.envrc`, re-run `direnv allow` and ensure your\n  shell config contains the direnv hook.\n\n## SQLPage Dev / Watch mode\n\nWhile you''re developing, Spry''s `dev-src.auto` generator should be used:\n\n```bash prepare-sqlpage-dev --descr \"Generate the dev-src.auto directory to work in SQLPage dev mode\"\n./spry.ts sp spc --fs dev-src.auto --destroy-first --conf sqlpage/sqlpage.json\n```\n\n```bash clean --descr \"Clean up the project directory''s generated artifacts\"\nrm -rf dev-src.auto\n```\n\nIn development mode, here’s the `--watch` convenience you can use so that\nwhenever you update `Spryfile.md`, it regenerates the SQLPage `dev-src.auto`,\nwhich is then picked up automatically by the SQLPage server:\n\n```bash\n./spry.ts sp spc --fs dev-src.auto --destroy-first --conf sqlpage/sqlpage.json --watch --with-sqlpage\n```\n\n- `--watch` turns on watching all `--md` files passed in (defaults to\n  `Spryfile.md`)\n- `--with-sqlpage` starts and stops SQLPage after each build\n\nRestarting SQLPage after each re-generation of dev-src.auto is **not**\nnecessary, so you can also use `--watch` without `--with-sqlpage` in one\nterminal window while keeping the SQLPage server running in another terminal\nwindow.\n\nIf you''re running SQLPage in another terminal window, use:\n\n```bash\n./spry.ts sp spc --fs dev-src.auto --destroy-first --conf sqlpage/sqlpage.json --watch\n```\n\n## SQLPage single database deployment mode\n\nAfter development is complete, the `dev-src.auto` can be removed and\nsingle-database deployment can be used:\n\n```bash deploy -C --descr \"Generate sqlpage_files table upsert SQL and push them to SQLite\"\nrm -rf dev-src.auto\n./spry.ts sp spc --package --conf sqlpage/sqlpage.json | sqlite3 scf-2025.3.sqlite.db\n```\n\n## Raw SQL\n\nThis raw SQL will be placed into HEAD/TAIL. As an example, copy the same file\ntwice to show how it can be renamed.\n\n```include --base ../../../lib/universal\nsql *.sql sql.d/tail\nsql schema-info.dml.sqlite.sql sql.d/tail/0000.sql\n```\n\n💡 `schema-info.dml.sqlite.sql` will appear in the output as\n`sql.d/tail/0000.sql` and `sql.d/tail/schema-info.dml.sqlite.sql` (doing it\ntwice just for testing).\n\n## Layout\n\nThis cell instructs Spry to automatically inject the SQL `PARTIAL` into all\nSQLPage content cells. The name `global-layout.sql` is not significant (it''s\nrequired by Spry but only used for reference), but the `--inject **/*` argument\nis how matching occurs. The `--BEGIN` and `--END` comments are not required by\nSpry but make it easier to trace where _partial_ injections are occurring.\n\n⚠️ Content injection content happens _before_ any other interpolation so the\nfinal interpolation for injected content will occur in the destination cell.\n\n```sql PARTIAL global-layout.sql --inject **/*\n-- BEGIN: PARTIAL global-layout.sql\nSELECT ''shell'' AS component,\n       ''Secure Controls Framework (SCF) Explorer'' AS title,\n       NULL AS icon,\n       ''/assets/brand/content-assembler.ico'' AS favicon,\n       ''/assets/brand/compliance-explorer.png'' AS image,\n       ''fluid'' AS layout,\n       true AS fixed_top_menu,\n       ''index.sql'' AS link,\n       ''{\"link\":\"/index.sql\",\"title\":\"Home\"}'' AS menu_item;\n\nSET resource_json = sqlpage.read_file_as_text(''spry.d/auto/resource/${path}.auto.json'');\nSET page_title  = json_extract($resource_json, ''$.route.caption'');\nSET page_path = json_extract($resource_json, ''$.route.path'');\n\n${ctx.breadcrumbs()}\n\n-- END: PARTIAL global-layout.sql\n```\n\nGet the brand assets and store them into the SQLPage content stream. They will\nbe stored as `assets/brand/*` because `--base` is `https://www.surveilr.com/`\nand destination is set to `.`.\n\n```contribute sqlpage_files --base https://www.surveilr.com/\nhttps://www.surveilr.com/assets/brand/content-assembler.ico .\nhttps://www.surveilr.com/assets/brand/compliance-explorer.png .\n```\n\n## SCF Home Page\n\nIndex page which automatically generates links to all `/scf` pages.\n\n```sql index.sql { route: { caption: \"Home\" } }\n-- locals: ${Object.keys(__l).join(\", \")}\n-- mdastNode: ${safeJsonStringify(cell)}\nSET routes_json = sqlpage.read_file_as_text(''spry.d/auto/route/forest.auto.json'');\nSET root_path   = ''/scf'';\n\nSELECT ''card'' AS component, '''' AS title, 2 AS columns;\nSELECT\n  IFNULL(json_extract(c.value,''$.payloads[0].caption''),\n         json_extract(c.value,''$.basename''))                         AS title,\n  json_extract(c.value,''$.payloads[0].description'')                  AS description_md,\n  json_extract(c.value,''$.path'')                                     AS link\nFROM json_each(\n       json_extract(\n         (SELECT jt.value\n          FROM json_tree(json($routes_json)) AS jt\n          WHERE jt.type=''object''\n            AND json_extract(jt.value,''$.path'') = $root_path\n          LIMIT 1),\n         ''$.children''\n       )\n     ) AS c\nWHERE IFNULL(json_extract(c.value,''$.virtual''), 0) <> 1;\n```\n\n## Unpivoted page\n\n```sql scf/regime_control_unpivoted.sql { route: { caption: \"Regime mappings\" } }\n-- @route.description \"One row per (SCF control, regime column) with the raw cell value and regime column ordinal. Use this as the base long-form dataset.\"\n\nSELECT ''text'' AS component, $page_title AS title;\n\n${paginate(\"scf_regime_control_unpivoted\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       ''SCF #'' as  markdown,\n       ''Regime'' as  markdown,\n       TRUE     AS search;  \nSELECT\n  ${md.link(\"regime_label\", [`''details/regime.sql?regime=''`, \"regime_label\"])} as Regime,\n  ${md.link(\"scf_no\", [`''details/regime_control_unpivoted_details.sql?scf_no=''`, \"scf_no\"])} as \"SCF #\",\n  scf_domain AS \"SCF Domain\",\n  scf_control AS \"SCF Control\",\n  scf_control_question AS \"SCF Control Question\",\n  regime_raw_value AS \"Regime Marker\",\n  regime_column_ordinal AS \"Regime Column Ordinal\"\nFROM \"scf_regime_control_unpivoted\"\nORDER BY scf_no, regime_column_ordinal\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Regime Controls page\n\n```sql scf/regime_control.sql { route: { caption: \"Clean list of regime mappings\"} }\n-- @route.description \"Filtered projection of the unpivoted data. One row per (SCF control, regime) keeping key control fields and the regime''s raw marker.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n${paginate(\"scf_regime_control\")}\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       TRUE     AS search,\n       ''SCF #'' as  markdown,\n       ''Regime'' AS markdown;              -- interpret the \"Regime\" column as Markdown\nSELECT  \n  ${md.link(\"scf_no\", [`''details/regime_control_unpivoted_details.sql?scf_no=''`, \"scf_no\"])} as \"SCF #\",\n  scf_control AS \"SCF Control\",\n  scf_control_question AS \"SCF Control Question\",\n  regime_raw_value AS \"Regime Marker\"\nFROM \"scf_regime_control\"\nORDER BY scf_no\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Regime Count page\n\n```sql scf/regime_count.sql { route: { caption: \"Controls per regime (totals)\"} }\n-- @route.description \"Filtered projection of the unpivoted data. One row per (SCF control, regime) keeping key control fields and the regime''s raw marker.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n${paginate(\"scf_regime_count\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       ''Regime'' as  markdown,\n       TRUE     AS search;              \nSELECT \n  ${md.link(\"regime\", [`''details/regime.sql?regime=''`, \"regime\"])} as Regime,\n  control_count AS \"Controls\"\nFROM \"scf_regime_count\"\nORDER BY control_count DESC, regime\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Domain Count page\n\n```sql scf/regime_domain_count.sql { route: { caption: \"Domain x Regime counts\"} }\n-- @route.description \"Counts of controls grouped by SCF domain and regime. Useful for heatmaps showing domain coverage by regime.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n${paginate(\"scf_regime_domain_count\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       TRUE     AS search;              \nSELECT\n  domain AS \"Domain\",\n  control_count AS \"Controls\"\nFROM \"scf_regime_domain_count\"\nORDER BY control_count DESC, domain\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Coverage page\n\n```sql scf/regime_domain_coverage.sql { route: { caption: \"Domain coverage % by regime\"} }\n-- @route.description \"For each SCF domain and regime, shows mapped control count, total controls in the domain, and the percent coverage.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n ${paginate(\"scf_regime_domain_coverage\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       ''Regime'' as  markdown,\n       TRUE     AS search;              \nSELECT\n  scf_domain AS \"Domain\", \n  ${md.link(\"regime_label\", [`''details/regime.sql?regime=''`, \"regime_label\"])} as Regime,\n  mapped_controls AS \"Mapped Controls\",\n  domain_total_controls AS \"Total Controls\",\n  coverage_pct AS \"Coverage %\"\nFROM \"scf_regime_domain_coverage\"\nORDER BY scf_domain, coverage_pct DESC, regime_label\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Regime Rank page\n\n```sql scf/regime_domain_rank.sql { route: { caption: \"Top regimes within each domain\"} }\n-- @route.description \"Ranks regimes inside each SCF domain by count of mapped controls (ties broken by regime name).\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n \n ${paginate(\"scf_regime_domain_rank\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       ''Regime'' as  markdown,\n       TRUE     AS search;              \nSELECT\n  scf_domain AS \"Domain\",   \n  ${md.link(\"regime_label\", [`''details/regime.sql?regime=''`, \"regime_label\"])} as Regime,\n  control_count AS \"Controls\",\n  regime_rank_in_domain AS \"Rank in Domain\"\nFROM \"scf_regime_domain_rank\"\nORDER BY scf_domain, regime_rank_in_domain, regime_label\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Jaccard page\n\n```sql scf/regime_overlap_jaccard.sql { route: { caption: \"Regime overlap (Jaccard)\"} }\n-- @route.description \"Pairwise overlap of regimes based on shared SCF controls, including each regime''s total and the Jaccard similarity score.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n${paginate(\"scf_regime_overlap_jaccard\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       ''Regime A'' as  markdown,\n       ''Regime B'' as  markdown,\n       TRUE     AS search;              \nSELECT \n  ${md.link(\"regime_a\", [`''details/regime.sql?regime=''`, \"regime_a\"])} as \"Regime A\",\n  ${md.link(\"regime_b\", [`''details/regime.sql?regime=''`, \"regime_b\"])} as \"Regime B\",   \n  in_both AS \"In Both\",\n  a_total AS \"A Total\",\n  b_total AS \"B Total\",\n  jaccard AS \"Jaccard\"\nFROM \"scf_regime_overlap_jaccard\"\nORDER BY jaccard DESC, in_both DESC, regime_a, regime_b\n${pagination.limit}; \n${pagination.navigation}\n```\n\n```sql scf/details/regime_control_unpivoted_details.sql { route: { caption: \"Long form of SCF x Regime mappings details\" } }\nSELECT\n  ''text'' AS component,\n $page_title||'' for SCF # ''||$scf_no AS title;\n\n${paginate(\"scf_regime_control_unpivoted\", \"WHERE scf_no = $scf_no\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       \"Regime\" as  markdown,\n       ''SCF #'' as  markdown,\n       TRUE     AS search;              \nSELECT\n  ${md.link(\"regime_label\", [`''regime.sql?regime=''`, \"regime_label\"])} as \"Regime\", \n  ${md.link(\"scf_no\", [`''regime_control_unpivoted_details.sql?scf_no=''`, \"scf_no\"])} as \"SCF #\",\n  scf_domain AS \"SCF Domain\",\n  scf_control AS \"SCF Control\",\n  scf_control_question AS \"SCF Control Question\",\n  regime_raw_value AS \"Regime Marker\",\n  regime_column_ordinal AS \"Regime Column Ordinal\"\nFROM \"scf_regime_control_unpivoted\"\nWHERE scf_no = $scf_no\nORDER BY scf_no, regime_column_ordinal\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Controls per regime (totals) details page\n\n```sql scf/details/regime.sql { route: { caption: \"Controls per regime (totals) details\" } }\nSELECT\n  ''text'' AS component,\n $page_title||'' for ''||$regime AS title;\n\n${paginate(\"scf_regime_control\", \"WHERE regime_label = $regime\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       \"SCF #\" as markdown,\n       TRUE     AS search;              \nSELECT  \n  ${md.link(\"scf_no\", [`''regime_control_unpivoted_details.sql?scf_no=''`, \"scf_no\"])} as \"SCF #\",\n  scf_control AS \"SCF Control\",\n  scf_control_question AS \"SCF Control Question\",\n  regime_raw_value AS \"Regime Marker\"\nFROM \"scf_regime_control\"\nWHERE regime_label = $regime\nORDER BY scf_no\n${pagination.limit}; \n${pagination.navWithParams(\"regime\")}\n```\n\n## Threat Catalog Page\n\n```sql scf/threat_catalog.sql { route: { caption: \"Threat Catalog\", description: \"Threat Catalog\" } }\nSELECT ''table'' as component,\n       TRUE as sort,\n       TRUE as search;\nSELECT\n    \"Threat Grouping\",\n    \"Threat #\",\n    \"Threat Description\",\n    \"≥ 5% of pre-tax income\",\n    \"≥ 0.5% of total assets\",\n    \"≥ 1% of total equity\",\n    \"≥ 0.5% of total revenue\"\nFROM scf_threat_catalog;\n```\n\n## Controls Library page\n\n```sql scf/controls.sql { route: { caption: \"Controls Library\"} }\n-- @route.description \"Discover and understand compliance controls across different regulatory frameworks. Select your applicable regimes to identify your control responsibilities.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n\n ${paginate(\"scf_regime_count\")}\n\n    SELECT ''table'' AS component,\n          TRUE     AS sort,\n          ''Regime'' as  markdown,\n          TRUE     AS search;              \n    SELECT  \n      ${md.link(\"regime\", [`''details/regime.sql?regime=''`, \"regime\"])} as Regime,\n      control_count AS \"Controls\"\n    FROM \"scf_regime_count\"\n    ORDER BY control_count DESC, regime\n    ${pagination.limit}; \n    ${pagination.navigation}\n```\n\n## Regime details page\n\n```sql scf/details/regime_details.sql { route: { caption: \"Control details\" } }\n SELECT ''card'' AS component,\n           $page_title AS title,\n           1 AS columns;\nSELECT\n      $regime||'' ''||$scf_no AS title,\n      ''**SCF Domain:** '' || scf_domain || ''  \n\n'' ||\n      ''**SCF Control:** '' || scf_control || ''  \n\n'' ||\n      ''**SCF Control Question:** '' || scf_control_question || ''  \n\n'' ||\n      ''**Regime Marker:** '' || regime_raw_value \n      AS description_md\n  FROM \"scf_regime_control_unpivoted\"\nWHERE scf_no = $scf_no\nAND regime_label = $regime;\n```\n"},"mdSrcText":"---\nsqlpage-conf:\n  database_url: ${env.SPRY_DB}\n  web_root: \"./dev-src.auto\"\n  allow_exec: true\n  port: ${env.PORT}\n---\n\n# Secure Controls Framework (SCF) SQLPage Application\n\nThis script automates the conversion of the latest Secure Controls Framework\n(SCF) Excel workbook from the\n[official SCF GitHub repository](https://github.com/securecontrolsframework/securecontrolsframework)\ninto a structured SQLite database.\n\n- Uses Spry to manage tasks and generate the SQLPage presentation layer.\n- Uses DuckDB with its built-in `excel` and `sqlite` extensions.\n\n## Spry Axiom configuration\n\n`code DEFAULTS` is a special directive use by Spry''s Axiom library to supply\ndefault flags to specific code blocks like `sql`, `text`, etc. allowing them to\nbe interpolatable (`${...}`) and injectable (using `PARTIAL`s) by default\ninstead of having to pass `--interpolate` and `--injectable` into each code\ncell. 💡 `code DEFAULTS` is necessary in Spry SQLPage playbooks to tell Axiom\nhow to treat `sql` code fenced blocks.\n\n```code DEFAULTS\nsql * --interpolate --injectable\n```\n\nThe following example shows how arbitrary files can be \"contributed\" to\n`sqlpage_files`. `--base` should be relative to the current working directory\n(CWD). 💡 It''s included just as an examplar and is not required:\n\n```contribute sqlpage_files --base ../../../lib/axiom/fixture/sundry\n**/* SUNDRY\n```\n\nThe following example shows how template files can be \"contributed\" to\n`sqlpage_files` but only when `--package` is being used. Spry picks them up from\n`../sqlpage/templates/*` and store them in `templates/*` path in `sqlpage_files`\ntable only during `--package` operation:\n\n```contribute sqlpage_files --base sqlpage/templates --mode package\n**/* templates --mime text/plain\n```\n\n💡 You should use the above technique if you ever create custom\n`sqlplage/templates` files that you want included in the database.\n\n## Setup\n\nDownload the SCF Excel workbook from the GitHub repo and place it into the same\ndirectory as this `README.md` and then run `spry.ts task prepare-db`. We supply\nour own `#!/usr/bin/env -S bash` shebang since we have comments in the shell\nscript.\n\n```bash prepare-db --descr \"Delete and recreate the SQLite database used by SQLPage\"\n#!/usr/bin/env -S bash\nrm -f scf-2025.3.sqlite.db                  # will be re-created by DuckDB `ATTACH`\ncat prepare.duckdb.sql | duckdb \":memory:\"  # DuckDB processes in memory but creates SQLite DB\n```\n\n## Environment variables and .envrc\n\nThis project reads configuration from environment variables. Two variables you\nwill commonly set in development are:\n\n- `SPRY_DB` — the database connection URL used by SQLPage and Spry. Example\n  value used here: `sqlite://scf-2025.3.sqlite.db?mode=rwc`\n  - Scheme: `sqlite://` followed by a path (relative or absolute) to the SQLite\n    file.\n  - Query `mode=rwc` tells SQLite/DuckDB to open the file for read/write and\n    create it if missing.\n  - If you prefer a path under a `data/` directory, set e.g.\n    `sqlite://./data/scf-2025.3.sqlite.db?mode=rwc`.\n\n- `PORT` — the TCP port the local SQLPage server or other local web component\n  should listen on (example: `9227`).\n\nRecommended practice is to keep these values in a local, directory-scoped\nenvironment file. If you use direnv (recommended), create a file named `.envrc`\nin this directory.\n\nPOSIX-style example (bash/zsh):\n\n```envrc prepare-env -C ./.envrc -X --gitignore --descr \"Generate .envrc file and add it to local .gitignore if it''s not already there\"\nexport SPRY_DB=\"sqlite://scf-2025.3.sqlite.db?mode=rwc\"\nexport PORT=9227\n```\n\nThen run `direnv allow` in this project directory to load the `.envrc` into your\nshell environment. direnv will evaluate `.envrc` only after you explicitly allow\nit.\n\n## Security and repository hygiene\n\n- Never commit secrets or production credentials into `.envrc`. Treat `.envrc`\n  like a local-only file.\n- Add `.envrc` to your local `.gitignore` if you keep secrets there.\n  Alternatively commit a `.envrc.example` or `.envrc.sample` with safe,\n  non-secret defaults to document expected variables.\n- The SQLite file (e.g. `scf-2025.3.sqlite.db`) is a binary database file — you\n  will usually not check this into version control. Add that filename or the\n  `data/` directory to `.gitignore` as well.\n\nWhy these variables matter here\n\n- The YAML header at the top of this `Spryfile.md` reads\n  `database_url: ${env.SPRY_DB}` and `port: ${env.PORT}` — Spry and the SQLPage\n  tooling will substitute those environment values when building or serving the\n  site.\n- If `SPRY_DB` is not set, the tooling may fail to find the database or fall\n  back to defaults; explicitly setting it ensures predictable, repeatable dev\n  runs.\n\nQuick troubleshooting\n\n- If the server does not start on the expected port, verify `echo $PORT` (or\n  `echo $SPRY_DB`) in your shell to confirm values are loaded.\n- If direnv appears not to load `.envrc`, re-run `direnv allow` and ensure your\n  shell config contains the direnv hook.\n\n## SQLPage Dev / Watch mode\n\nWhile you''re developing, Spry''s `dev-src.auto` generator should be used:\n\n```bash prepare-sqlpage-dev --descr \"Generate the dev-src.auto directory to work in SQLPage dev mode\"\n./spry.ts sp spc --fs dev-src.auto --destroy-first --conf sqlpage/sqlpage.json\n```\n\n```bash clean --descr \"Clean up the project directory''s generated artifacts\"\nrm -rf dev-src.auto\n```\n\nIn development mode, here’s the `--watch` convenience you can use so that\nwhenever you update `Spryfile.md`, it regenerates the SQLPage `dev-src.auto`,\nwhich is then picked up automatically by the SQLPage server:\n\n```bash\n./spry.ts sp spc --fs dev-src.auto --destroy-first --conf sqlpage/sqlpage.json --watch --with-sqlpage\n```\n\n- `--watch` turns on watching all `--md` files passed in (defaults to\n  `Spryfile.md`)\n- `--with-sqlpage` starts and stops SQLPage after each build\n\nRestarting SQLPage after each re-generation of dev-src.auto is **not**\nnecessary, so you can also use `--watch` without `--with-sqlpage` in one\nterminal window while keeping the SQLPage server running in another terminal\nwindow.\n\nIf you''re running SQLPage in another terminal window, use:\n\n```bash\n./spry.ts sp spc --fs dev-src.auto --destroy-first --conf sqlpage/sqlpage.json --watch\n```\n\n## SQLPage single database deployment mode\n\nAfter development is complete, the `dev-src.auto` can be removed and\nsingle-database deployment can be used:\n\n```bash deploy -C --descr \"Generate sqlpage_files table upsert SQL and push them to SQLite\"\nrm -rf dev-src.auto\n./spry.ts sp spc --package --conf sqlpage/sqlpage.json | sqlite3 scf-2025.3.sqlite.db\n```\n\n## Raw SQL\n\nThis raw SQL will be placed into HEAD/TAIL. As an example, copy the same file\ntwice to show how it can be renamed.\n\n```include --base ../../../lib/universal\nsql *.sql sql.d/tail\nsql schema-info.dml.sqlite.sql sql.d/tail/0000.sql\n```\n\n💡 `schema-info.dml.sqlite.sql` will appear in the output as\n`sql.d/tail/0000.sql` and `sql.d/tail/schema-info.dml.sqlite.sql` (doing it\ntwice just for testing).\n\n## Layout\n\nThis cell instructs Spry to automatically inject the SQL `PARTIAL` into all\nSQLPage content cells. The name `global-layout.sql` is not significant (it''s\nrequired by Spry but only used for reference), but the `--inject **/*` argument\nis how matching occurs. The `--BEGIN` and `--END` comments are not required by\nSpry but make it easier to trace where _partial_ injections are occurring.\n\n⚠️ Content injection content happens _before_ any other interpolation so the\nfinal interpolation for injected content will occur in the destination cell.\n\n```sql PARTIAL global-layout.sql --inject **/*\n-- BEGIN: PARTIAL global-layout.sql\nSELECT ''shell'' AS component,\n       ''Secure Controls Framework (SCF) Explorer'' AS title,\n       NULL AS icon,\n       ''/assets/brand/content-assembler.ico'' AS favicon,\n       ''/assets/brand/compliance-explorer.png'' AS image,\n       ''fluid'' AS layout,\n       true AS fixed_top_menu,\n       ''index.sql'' AS link,\n       ''{\"link\":\"/index.sql\",\"title\":\"Home\"}'' AS menu_item;\n\nSET resource_json = sqlpage.read_file_as_text(''spry.d/auto/resource/${path}.auto.json'');\nSET page_title  = json_extract($resource_json, ''$.route.caption'');\nSET page_path = json_extract($resource_json, ''$.route.path'');\n\n${ctx.breadcrumbs()}\n\n-- END: PARTIAL global-layout.sql\n```\n\nGet the brand assets and store them into the SQLPage content stream. They will\nbe stored as `assets/brand/*` because `--base` is `https://www.surveilr.com/`\nand destination is set to `.`.\n\n```contribute sqlpage_files --base https://www.surveilr.com/\nhttps://www.surveilr.com/assets/brand/content-assembler.ico .\nhttps://www.surveilr.com/assets/brand/compliance-explorer.png .\n```\n\n## SCF Home Page\n\nIndex page which automatically generates links to all `/scf` pages.\n\n```sql index.sql { route: { caption: \"Home\" } }\n-- locals: ${Object.keys(__l).join(\", \")}\n-- mdastNode: ${safeJsonStringify(cell)}\nSET routes_json = sqlpage.read_file_as_text(''spry.d/auto/route/forest.auto.json'');\nSET root_path   = ''/scf'';\n\nSELECT ''card'' AS component, '''' AS title, 2 AS columns;\nSELECT\n  IFNULL(json_extract(c.value,''$.payloads[0].caption''),\n         json_extract(c.value,''$.basename''))                         AS title,\n  json_extract(c.value,''$.payloads[0].description'')                  AS description_md,\n  json_extract(c.value,''$.path'')                                     AS link\nFROM json_each(\n       json_extract(\n         (SELECT jt.value\n          FROM json_tree(json($routes_json)) AS jt\n          WHERE jt.type=''object''\n            AND json_extract(jt.value,''$.path'') = $root_path\n          LIMIT 1),\n         ''$.children''\n       )\n     ) AS c\nWHERE IFNULL(json_extract(c.value,''$.virtual''), 0) <> 1;\n```\n\n## Unpivoted page\n\n```sql scf/regime_control_unpivoted.sql { route: { caption: \"Regime mappings\" } }\n-- @route.description \"One row per (SCF control, regime column) with the raw cell value and regime column ordinal. Use this as the base long-form dataset.\"\n\nSELECT ''text'' AS component, $page_title AS title;\n\n${paginate(\"scf_regime_control_unpivoted\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       ''SCF #'' as  markdown,\n       ''Regime'' as  markdown,\n       TRUE     AS search;  \nSELECT\n  ${md.link(\"regime_label\", [`''details/regime.sql?regime=''`, \"regime_label\"])} as Regime,\n  ${md.link(\"scf_no\", [`''details/regime_control_unpivoted_details.sql?scf_no=''`, \"scf_no\"])} as \"SCF #\",\n  scf_domain AS \"SCF Domain\",\n  scf_control AS \"SCF Control\",\n  scf_control_question AS \"SCF Control Question\",\n  regime_raw_value AS \"Regime Marker\",\n  regime_column_ordinal AS \"Regime Column Ordinal\"\nFROM \"scf_regime_control_unpivoted\"\nORDER BY scf_no, regime_column_ordinal\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Regime Controls page\n\n```sql scf/regime_control.sql { route: { caption: \"Clean list of regime mappings\"} }\n-- @route.description \"Filtered projection of the unpivoted data. One row per (SCF control, regime) keeping key control fields and the regime''s raw marker.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n${paginate(\"scf_regime_control\")}\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       TRUE     AS search,\n       ''SCF #'' as  markdown,\n       ''Regime'' AS markdown;              -- interpret the \"Regime\" column as Markdown\nSELECT  \n  ${md.link(\"scf_no\", [`''details/regime_control_unpivoted_details.sql?scf_no=''`, \"scf_no\"])} as \"SCF #\",\n  scf_control AS \"SCF Control\",\n  scf_control_question AS \"SCF Control Question\",\n  regime_raw_value AS \"Regime Marker\"\nFROM \"scf_regime_control\"\nORDER BY scf_no\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Regime Count page\n\n```sql scf/regime_count.sql { route: { caption: \"Controls per regime (totals)\"} }\n-- @route.description \"Filtered projection of the unpivoted data. One row per (SCF control, regime) keeping key control fields and the regime''s raw marker.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n${paginate(\"scf_regime_count\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       ''Regime'' as  markdown,\n       TRUE     AS search;              \nSELECT \n  ${md.link(\"regime\", [`''details/regime.sql?regime=''`, \"regime\"])} as Regime,\n  control_count AS \"Controls\"\nFROM \"scf_regime_count\"\nORDER BY control_count DESC, regime\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Domain Count page\n\n```sql scf/regime_domain_count.sql { route: { caption: \"Domain x Regime counts\"} }\n-- @route.description \"Counts of controls grouped by SCF domain and regime. Useful for heatmaps showing domain coverage by regime.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n${paginate(\"scf_regime_domain_count\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       TRUE     AS search;              \nSELECT\n  domain AS \"Domain\",\n  control_count AS \"Controls\"\nFROM \"scf_regime_domain_count\"\nORDER BY control_count DESC, domain\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Coverage page\n\n```sql scf/regime_domain_coverage.sql { route: { caption: \"Domain coverage % by regime\"} }\n-- @route.description \"For each SCF domain and regime, shows mapped control count, total controls in the domain, and the percent coverage.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n ${paginate(\"scf_regime_domain_coverage\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       ''Regime'' as  markdown,\n       TRUE     AS search;              \nSELECT\n  scf_domain AS \"Domain\", \n  ${md.link(\"regime_label\", [`''details/regime.sql?regime=''`, \"regime_label\"])} as Regime,\n  mapped_controls AS \"Mapped Controls\",\n  domain_total_controls AS \"Total Controls\",\n  coverage_pct AS \"Coverage %\"\nFROM \"scf_regime_domain_coverage\"\nORDER BY scf_domain, coverage_pct DESC, regime_label\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Regime Rank page\n\n```sql scf/regime_domain_rank.sql { route: { caption: \"Top regimes within each domain\"} }\n-- @route.description \"Ranks regimes inside each SCF domain by count of mapped controls (ties broken by regime name).\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n \n ${paginate(\"scf_regime_domain_rank\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       ''Regime'' as  markdown,\n       TRUE     AS search;              \nSELECT\n  scf_domain AS \"Domain\",   \n  ${md.link(\"regime_label\", [`''details/regime.sql?regime=''`, \"regime_label\"])} as Regime,\n  control_count AS \"Controls\",\n  regime_rank_in_domain AS \"Rank in Domain\"\nFROM \"scf_regime_domain_rank\"\nORDER BY scf_domain, regime_rank_in_domain, regime_label\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Jaccard page\n\n```sql scf/regime_overlap_jaccard.sql { route: { caption: \"Regime overlap (Jaccard)\"} }\n-- @route.description \"Pairwise overlap of regimes based on shared SCF controls, including each regime''s total and the Jaccard similarity score.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n${paginate(\"scf_regime_overlap_jaccard\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       ''Regime A'' as  markdown,\n       ''Regime B'' as  markdown,\n       TRUE     AS search;              \nSELECT \n  ${md.link(\"regime_a\", [`''details/regime.sql?regime=''`, \"regime_a\"])} as \"Regime A\",\n  ${md.link(\"regime_b\", [`''details/regime.sql?regime=''`, \"regime_b\"])} as \"Regime B\",   \n  in_both AS \"In Both\",\n  a_total AS \"A Total\",\n  b_total AS \"B Total\",\n  jaccard AS \"Jaccard\"\nFROM \"scf_regime_overlap_jaccard\"\nORDER BY jaccard DESC, in_both DESC, regime_a, regime_b\n${pagination.limit}; \n${pagination.navigation}\n```\n\n```sql scf/details/regime_control_unpivoted_details.sql { route: { caption: \"Long form of SCF x Regime mappings details\" } }\nSELECT\n  ''text'' AS component,\n $page_title||'' for SCF # ''||$scf_no AS title;\n\n${paginate(\"scf_regime_control_unpivoted\", \"WHERE scf_no = $scf_no\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       \"Regime\" as  markdown,\n       ''SCF #'' as  markdown,\n       TRUE     AS search;              \nSELECT\n  ${md.link(\"regime_label\", [`''regime.sql?regime=''`, \"regime_label\"])} as \"Regime\", \n  ${md.link(\"scf_no\", [`''regime_control_unpivoted_details.sql?scf_no=''`, \"scf_no\"])} as \"SCF #\",\n  scf_domain AS \"SCF Domain\",\n  scf_control AS \"SCF Control\",\n  scf_control_question AS \"SCF Control Question\",\n  regime_raw_value AS \"Regime Marker\",\n  regime_column_ordinal AS \"Regime Column Ordinal\"\nFROM \"scf_regime_control_unpivoted\"\nWHERE scf_no = $scf_no\nORDER BY scf_no, regime_column_ordinal\n${pagination.limit}; \n${pagination.navigation}\n```\n\n## Controls per regime (totals) details page\n\n```sql scf/details/regime.sql { route: { caption: \"Controls per regime (totals) details\" } }\nSELECT\n  ''text'' AS component,\n $page_title||'' for ''||$regime AS title;\n\n${paginate(\"scf_regime_control\", \"WHERE regime_label = $regime\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       \"SCF #\" as markdown,\n       TRUE     AS search;              \nSELECT  \n  ${md.link(\"scf_no\", [`''regime_control_unpivoted_details.sql?scf_no=''`, \"scf_no\"])} as \"SCF #\",\n  scf_control AS \"SCF Control\",\n  scf_control_question AS \"SCF Control Question\",\n  regime_raw_value AS \"Regime Marker\"\nFROM \"scf_regime_control\"\nWHERE regime_label = $regime\nORDER BY scf_no\n${pagination.limit}; \n${pagination.navWithParams(\"regime\")}\n```\n\n## Threat Catalog Page\n\n```sql scf/threat_catalog.sql { route: { caption: \"Threat Catalog\", description: \"Threat Catalog\" } }\nSELECT ''table'' as component,\n       TRUE as sort,\n       TRUE as search;\nSELECT\n    \"Threat Grouping\",\n    \"Threat #\",\n    \"Threat Description\",\n    \"≥ 5% of pre-tax income\",\n    \"≥ 0.5% of total assets\",\n    \"≥ 1% of total equity\",\n    \"≥ 0.5% of total revenue\"\nFROM scf_threat_catalog;\n```\n\n## Controls Library page\n\n```sql scf/controls.sql { route: { caption: \"Controls Library\"} }\n-- @route.description \"Discover and understand compliance controls across different regulatory frameworks. Select your applicable regimes to identify your control responsibilities.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n\n ${paginate(\"scf_regime_count\")}\n\n    SELECT ''table'' AS component,\n          TRUE     AS sort,\n          ''Regime'' as  markdown,\n          TRUE     AS search;              \n    SELECT  \n      ${md.link(\"regime\", [`''details/regime.sql?regime=''`, \"regime\"])} as Regime,\n      control_count AS \"Controls\"\n    FROM \"scf_regime_count\"\n    ORDER BY control_count DESC, regime\n    ${pagination.limit}; \n    ${pagination.navigation}\n```\n\n## Regime details page\n\n```sql scf/details/regime_details.sql { route: { caption: \"Control details\" } }\n SELECT ''card'' AS component,\n           $page_title AS title,\n           1 AS columns;\nSELECT\n      $regime||'' ''||$scf_no AS title,\n      ''**SCF Domain:** '' || scf_domain || ''  \n\n'' ||\n      ''**SCF Control:** '' || scf_control || ''  \n\n'' ||\n      ''**SCF Control Question:** '' || scf_control_question || ''  \n\n'' ||\n      ''**Regime Marker:** '' || regime_raw_value \n      AS description_md\n  FROM \"scf_regime_control_unpivoted\"\nWHERE scf_no = $scf_no\nAND regime_label = $regime;\n```\n","mdastRoot":{"children":[{"data":{"parsedFM":{"fm":"[Circular]"}},"position":{"end":{"column":4,"line":7,"offset":120},"start":{"column":1,"line":1,"offset":0}},"type":"yaml","value":"sqlpage-conf:\n  database_url: ${env.SPRY_DB}\n  web_root: \"./dev-src.auto\"\n  allow_exec: true\n  port: ${env.PORT}"},{"children":[{"position":{"end":{"column":54,"line":9,"offset":175},"start":{"column":3,"line":9,"offset":124}},"type":"text","value":"Secure Controls Framework (SCF) SQLPage Application"}],"depth":1,"position":{"end":{"column":54,"line":9,"offset":175},"start":{"column":1,"line":9,"offset":122}},"type":"heading"},{"children":[{"position":{"end":{"column":1,"line":13,"offset":284},"start":{"column":1,"line":11,"offset":177}},"type":"text","value":"This script automates the conversion of the latest Secure Controls Framework\n(SCF) Excel workbook from the\n"},{"children":[{"position":{"end":{"column":32,"line":13,"offset":315},"start":{"column":2,"line":13,"offset":285}},"type":"text","value":"official SCF GitHub repository"}],"position":{"end":{"column":101,"line":13,"offset":384},"start":{"column":1,"line":13,"offset":284}},"title":null,"type":"link","url":"https://github.com/securecontrolsframework/securecontrolsframework"},{"position":{"end":{"column":35,"line":14,"offset":419},"start":{"column":101,"line":13,"offset":384}},"type":"text","value":"\ninto a structured SQLite database."}],"position":{"end":{"column":35,"line":14,"offset":419},"start":{"column":1,"line":11,"offset":177}},"type":"paragraph"},{"children":[{"checked":null,"children":[{"children":[{"position":{"end":{"column":73,"line":16,"offset":493},"start":{"column":3,"line":16,"offset":423}},"type":"text","value":"Uses Spry to manage tasks and generate the SQLPage presentation layer."}],"position":{"end":{"column":73,"line":16,"offset":493},"start":{"column":3,"line":16,"offset":423}},"type":"paragraph"}],"position":{"end":{"column":73,"line":16,"offset":493},"start":{"column":1,"line":16,"offset":421}},"spread":false,"type":"listItem"},{"checked":null,"children":[{"children":[{"position":{"end":{"column":33,"line":17,"offset":526},"start":{"column":3,"line":17,"offset":496}},"type":"text","value":"Uses DuckDB with its built-in "},{"position":{"end":{"column":40,"line":17,"offset":533},"start":{"column":33,"line":17,"offset":526}},"type":"inlineCode","value":"excel"},{"position":{"end":{"column":45,"line":17,"offset":538},"start":{"column":40,"line":17,"offset":533}},"type":"text","value":" and "},{"position":{"end":{"column":53,"line":17,"offset":546},"start":{"column":45,"line":17,"offset":538}},"type":"inlineCode","value":"sqlite"},{"position":{"end":{"column":65,"line":17,"offset":558},"start":{"column":53,"line":17,"offset":546}},"type":"text","value":" extensions."}],"position":{"end":{"column":65,"line":17,"offset":558},"start":{"column":3,"line":17,"offset":496}},"type":"paragraph"}],"position":{"end":{"column":65,"line":17,"offset":558},"start":{"column":1,"line":17,"offset":494}},"spread":false,"type":"listItem"}],"ordered":false,"position":{"end":{"column":65,"line":17,"offset":558},"start":{"column":1,"line":16,"offset":421}},"spread":false,"start":null,"type":"list"},{"children":[{"position":{"end":{"column":28,"line":19,"offset":587},"start":{"column":4,"line":19,"offset":563}},"type":"text","value":"Spry Axiom configuration"}],"depth":2,"position":{"end":{"column":28,"line":19,"offset":587},"start":{"column":1,"line":19,"offset":560}},"type":"heading"},{"children":[{"position":{"end":{"column":16,"line":21,"offset":604},"start":{"column":1,"line":21,"offset":589}},"type":"inlineCode","value":"code DEFAULTS"},{"position":{"end":{"column":44,"line":22,"offset":709},"start":{"column":16,"line":21,"offset":604}},"type":"text","value":" is a special directive use by Spry''s Axiom library to supply\ndefault flags to specific code blocks like "},{"position":{"end":{"column":49,"line":22,"offset":714},"start":{"column":44,"line":22,"offset":709}},"type":"inlineCode","value":"sql"},{"position":{"end":{"column":51,"line":22,"offset":716},"start":{"column":49,"line":22,"offset":714}},"type":"text","value":", "},{"position":{"end":{"column":57,"line":22,"offset":722},"start":{"column":51,"line":22,"offset":716}},"type":"inlineCode","value":"text"},{"position":{"end":{"column":20,"line":23,"offset":765},"start":{"column":57,"line":22,"offset":722}},"type":"text","value":", etc. allowing them to\nbe interpolatable ("},{"position":{"end":{"column":28,"line":23,"offset":773},"start":{"column":20,"line":23,"offset":765}},"type":"inlineCode","value":"${...}"},{"position":{"end":{"column":52,"line":23,"offset":797},"start":{"column":28,"line":23,"offset":773}},"type":"text","value":") and injectable (using "},{"position":{"end":{"column":61,"line":23,"offset":806},"start":{"column":52,"line":23,"offset":797}},"type":"inlineCode","value":"PARTIAL"},{"position":{"end":{"column":27,"line":24,"offset":846},"start":{"column":61,"line":23,"offset":806}},"type":"text","value":"s) by default\ninstead of having to pass "},{"position":{"end":{"column":42,"line":24,"offset":861},"start":{"column":27,"line":24,"offset":846}},"type":"inlineCode","value":"--interpolate"},{"position":{"end":{"column":47,"line":24,"offset":866},"start":{"column":42,"line":24,"offset":861}},"type":"text","value":" and "},{"position":{"end":{"column":61,"line":24,"offset":880},"start":{"column":47,"line":24,"offset":866}},"type":"inlineCode","value":"--injectable"},{"position":{"end":{"column":10,"line":25,"offset":905},"start":{"column":61,"line":24,"offset":880}},"type":"text","value":" into each code\ncell. 💡 "},{"position":{"end":{"column":25,"line":25,"offset":920},"start":{"column":10,"line":25,"offset":905}},"type":"inlineCode","value":"code DEFAULTS"},{"position":{"end":{"column":14,"line":26,"offset":987},"start":{"column":25,"line":25,"offset":920}},"type":"text","value":" is necessary in Spry SQLPage playbooks to tell Axiom\nhow to treat "},{"position":{"end":{"column":19,"line":26,"offset":992},"start":{"column":14,"line":26,"offset":987}},"type":"inlineCode","value":"sql"},{"position":{"end":{"column":39,"line":26,"offset":