f_domain, coverage_pct DESC, regime_label\n${pagination.limit}; \n${pagination.navigation}"},{"children":[{"position":{"end":{"column":20,"line":378,"offset":13780},"start":{"column":4,"line":378,"offset":13764}},"type":"text","value":"Regime Rank page"}],"depth":2,"position":{"end":{"column":20,"line":378,"offset":13780},"start":{"column":1,"line":378,"offset":13761}},"type":"heading"},{"data":{"codeFM":{"attrs":{"route":{"caption":"Top regimes within each domain"}},"attrsText":"{ route: { caption: \"Top regimes within each domain\"} }","cli":"sql scf/regime_domain_rank.sql","cmdLang":"sql","fromPresets":["[Circular]"],"lang":"sql","langSpec":"[Circular]","meta":"scf/regime_domain_rank.sql { route: { caption: \"Top regimes within each domain\"} }","pi":{"args":["sql","scf/regime_domain_rank.sql"],"count":2,"flags":{"PRESET":true,"injectable":true,"interpolate":true,"scf/regime_domain_rank.sql":true},"pos":["scf/regime_domain_rank.sql"],"posCount":1}}},"isActionableCodeCandidate":true,"isBlob":false,"lang":"sql","language":"[Circular]","materializableIdentity":"scf/regime_domain_rank.sql","materializationArgs":{"deps":[],"graphs":[],"injectable":true,"injectedDep":[],"interpolate":true},"materializationAttrs":"[Circular]","meta":"scf/regime_domain_rank.sql { route: { caption: \"Top regimes within each domain\"} }","nature":"MATERIALIZABLE","position":{"end":{"column":4,"line":401,"offset":14549},"start":{"column":1,"line":380,"offset":13782}},"type":"code","value":"-- @route.description \"Ranks regimes inside each SCF domain by count of mapped controls (ties broken by regime name).\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n \n ${paginate(\"scf_regime_domain_rank\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       ''Regime'' as  markdown,\n       TRUE     AS search;              \nSELECT\n  scf_domain AS \"Domain\",   \n  ${md.link(\"regime_label\", [`''details/regime.sql?regime=''`, \"regime_label\"])} as Regime,\n  control_count AS \"Controls\",\n  regime_rank_in_domain AS \"Rank in Domain\"\nFROM \"scf_regime_domain_rank\"\nORDER BY scf_domain, regime_rank_in_domain, regime_label\n${pagination.limit}; \n${pagination.navigation}"},{"children":[{"position":{"end":{"column":16,"line":403,"offset":14566},"start":{"column":4,"line":403,"offset":14554}},"type":"text","value":"Jaccard page"}],"depth":2,"position":{"end":{"column":16,"line":403,"offset":14566},"start":{"column":1,"line":403,"offset":14551}},"type":"heading"},{"data":{"codeFM":{"attrs":{"route":{"caption":"Regime overlap (Jaccard)"}},"attrsText":"{ route: { caption: \"Regime overlap (Jaccard)\"} }","cli":"sql scf/regime_overlap_jaccard.sql","cmdLang":"sql","fromPresets":["[Circular]"],"lang":"sql","langSpec":"[Circular]","meta":"scf/regime_overlap_jaccard.sql { route: { caption: \"Regime overlap (Jaccard)\"} }","pi":{"args":["sql","scf/regime_overlap_jaccard.sql"],"count":2,"flags":{"PRESET":true,"injectable":true,"interpolate":true,"scf/regime_overlap_jaccard.sql":true},"pos":["scf/regime_overlap_jaccard.sql"],"posCount":1}}},"isActionableCodeCandidate":true,"isBlob":false,"lang":"sql","language":"[Circular]","materializableIdentity":"scf/regime_overlap_jaccard.sql","materializationArgs":{"deps":[],"graphs":[],"injectable":true,"injectedDep":[],"interpolate":true},"materializationAttrs":"[Circular]","meta":"scf/regime_overlap_jaccard.sql { route: { caption: \"Regime overlap (Jaccard)\"} }","nature":"MATERIALIZABLE","position":{"end":{"column":4,"line":429,"offset":15476},"start":{"column":1,"line":405,"offset":14568}},"type":"code","value":"-- @route.description \"Pairwise overlap of regimes based on shared SCF controls, including each regime''s total and the Jaccard similarity score.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n${paginate(\"scf_regime_overlap_jaccard\")}\n\nSELECT ''table'' AS component,\n       TRUE     AS sort,\n       ''Regime A'' as  markdown,\n       ''Regime B'' as  markdown,\n       TRUE     AS search;              \nSELECT \n  ${md.link(\"regime_a\", [`''details/regime.sql?regime=''`, \"regime_a\"])} as \"Regime A\",\n  ${md.link(\"regime_b\", [`''details/regime.sql?regime=''`, \"regime_b\"])} as \"Regime B\",   \n  in_both AS \"In Both\",\n  a_total AS \"A Total\",\n  b_total AS \"B Total\",\n  jaccard AS \"Jaccard\"\nFROM \"scf_regime_overlap_jaccard\"\nORDER BY jaccard DESC, in_both DESC, regime_a, regime_b\n${pagination.limit}; \n${pagination.navigation}"},{"data":{"codeFM":{"attrs":{"route":{"caption":"Long form of SCF x Regime mappings details"}},"attrsText":"{ route: { caption: \"Long form of SCF x Regime mappings details\" } }","cli":"sql scf/details/regime_control_unpivoted_details.sql","cmdLang":"sql","fromPresets":["[Circular]"],"lang":"sql","langSpec":"[Circular]","meta":"scf/details/regime_control_unpivoted_details.sql { route: { caption: \"Long form of SCF x Regime mappings details\" } }","pi":{"args":["sql","scf/details/regime_control_unpivoted_details.sql"],"count":2,"flags":{"PRESET":true,"injectable":true,"interpolate":true,"scf/details/regime_control_unpivoted_details.sql":true},"pos":["scf/details/regime_control_unpivoted_details.sql"],"posCount":1}}},"isActionableCodeCandidate":true,"isBlob":false,"lang":"sql","language":"[Circular]","materializableIdentity":"scf/details/regime_control_unpivoted_details.sql","materializationArgs":{"deps":[],"graphs":[],"injectable":true,"injectedDep":[],"interpolate":true},"materializationAttrs":"[Circular]","meta":"scf/details/regime_control_unpivoted_details.sql { route: { caption: \"Long form of SCF x Regime mappings details\" } }","nature":"MATERIALIZABLE","position":{"end":{"column":4,"line":456,"offset":16445},"start":{"column":1,"line":431,"offset":15478}},"type":"code","value":"SELECT\n  ''text'' AS component,\n $page_title||'' for SCF # ''||$scf_no AS title;\n\n${paginate(\"scf_regime_control_unpivoted\", \"WHERE scf_no = $scf_no\")}\n\nSELECT ''table'' AS component,\n       TRUE   