INSERT INTO sqlpage_files (path, contents, last_modified) VALUES ('scf/regime_domain_count.sql', '-- BEGIN: PARTIAL global-layout.sql
SELECT ''shell'' AS component,
       ''Secure Controls Framework (SCF) Explorer'' AS title,
       NULL AS icon,
       ''/assets/brand/content-assembler.ico'' AS favicon,
       ''/assets/brand/compliance-explorer.png'' AS image,
       ''fluid'' AS layout,
       true AS fixed_top_menu,
       ''index.sql'' AS link,
       ''{"link":"/index.sql","title":"Home"}'' AS menu_item;

SET resource_json = sqlpage.read_file_as_text(''spry.d/auto/resource/scf/regime_domain_count.sql.auto.json'');
SET page_title  = json_extract($resource_json, ''$.route.caption'');
SET page_path = json_extract($resource_json, ''$.route.path'');


    -- Read breadcrumbs from auto-generated JSON file
    SET breadcrumbs_json = sqlpage.read_file_as_text(''spry.d/auto/route/breadcrumbs.auto.json'');

    SELECT ''breadcrumb'' AS component;

    -- Home breadcrumb
    SELECT
      ''Home'' as title,
      ''/'' as link;

    -- Extract breadcrumb trail for the current path
    WITH breadcrumb_trail AS (
      SELECT
        value AS breadcrumb_item,
        key AS idx
      FROM json_each(json_extract($breadcrumbs_json, ''$.'' || $page_path))
    ),
    breadcrumb_nodes AS (
      SELECT
        idx,
        json_extract(breadcrumb_item, ''$.node.path'') AS path,
        json_extract(breadcrumb_item, ''$.node.basename'') AS basename,
        json_extract(breadcrumb_item, ''$.node.payloads[0].caption'') AS caption,
        json_extract(breadcrumb_item, ''$.node.payloads[0].abbreviatedCaption'') AS abbreviated_caption
      FROM breadcrumb_trail
    )
    SELECT
      COALESCE(
        abbreviated_caption,
        caption,
        REPLACE(
            REPLACE(
              REPLACE(basename, ''.sql'', ''''),
              ''-'', '' ''
            ),
            ''_'', '' ''
          )        
      ) AS title,
      CASE
        WHEN path LIKE ''%.sql'' THEN path
        ELSE path || ''/index.sql''
      END AS link
    FROM breadcrumb_nodes
    ORDER BY CAST(idx AS INTEGER);

    -- Current page breadcrumb (only if not root)
    SELECT
      $page_title as title,
      ''#'' as link
    WHERE LOWER($page_title) <> ''home'';
  

-- END: PARTIAL global-layout.sql
-- @route.description "Counts of controls grouped by SCF domain and regime. Useful for heatmaps showing domain coverage by regime."
SELECT
  ''text'' AS component,
 $page_title AS title;

SET total_rows = (SELECT COUNT(*) FROM scf_regime_domain_count );
SET limit = COALESCE($limit, 50);
SET offset = COALESCE($offset, 0);
SET total_pages = ($total_rows + $limit - 1) / $limit;
SET current_page = ($offset / $limit) + 1;

SELECT ''table'' AS component,
       TRUE     AS sort,
       TRUE     AS search;              
SELECT
  domain AS "Domain",
  control_count AS "Controls"
FROM "scf_regime_domain_count"
ORDER BY control_count DESC, domain
LIMIT $limit OFFSET $offset; 

          SELECT ''text'' AS component,
              (SELECT CASE WHEN CAST($current_page AS INTEGER) > 1 THEN ''[Previous](?limit='' || $limit || ''&offset='' || ($offset - $limit) || '')'' ELSE '''' END)
              || '' ''
              || ''(Page '' || $current_page || '' of '' || $total_pages || ") "
              || (SELECT CASE WHEN CAST($current_page AS INTEGER) < CAST($total_pages AS INTEGER) THEN ''[Next](?limit='' || $limit || ''&offset='' || ($offset + $limit) || '')'' ELSE '''' END)
              AS contents_md
          ;
        ', CURRENT_TIMESTAMP) ON CONFLICT(path) DO UPDATE SET contents = excluded.contents, last_modified = CURRENT_TIMESTAMP WHERE sqlpage_files.contents <> excluded.contents;
