  "value": "-- @route.description \"Discover and understand compliance controls across different regulatory frameworks. Select your applicable regimes to identify your control responsibilities.\"\nSELECT\n  ''text'' AS component,\n $page_title AS title;\n\n\n ${paginate(\"scf_regime_count\")}\n\n    SELECT ''table'' AS component,\n          TRUE     AS sort,\n          ''Regime'' as  markdown,\n          TRUE     AS search;              \n    SELECT  \n      ${md.link(\"regime\", [`''details/regime.sql?regime=''`, \"regime\"])} as Regime,\n      control_count AS \"Controls\"\n    FROM \"scf_regime_count\"\n    ORDER BY control_count DESC, regime\n    ${pagination.limit}; \n    ${pagination.navigation}"
}', CURRENT_TIMESTAMP) ON CONFLICT(path) DO UPDATE SET contents = excluded.contents, last_modified = CURRENT_TIMESTAMP WHERE sqlpage_files.contents <> excluded.contents;
