SELECT * FROM t;

DROP VIEW IF EXISTS navigation_breadcrumb;
CREATE VIEW navigation_breadcrumb AS
WITH t(path, depth, crumb_path, crumb_basename) AS (
  VALUES
  ('/', 0, '/', '/'),
('/scf', 0, '/', '/'),
('/scf', 1, '/scf', 'scf')
)
SELECT * FROM t;

DROP VIEW IF EXISTS navigation_child;
CREATE VIEW navigation_child AS
SELECT p.path AS parent_path, c.path AS child_path, c.basename AS child_basename, c.virtual, c.is_index
FROM navigation_node p
JOIN navigation_node c ON c.parent_path = p.path;

DROP VIEW IF EXISTS navigation_descendant;
CREATE VIEW navigation_descendant AS
WITH RECURSIVE d(root_path, path, depth) AS (
  SELECT n.path AS root_path, n.path, 0 AS depth FROM navigation_node n
  UNION ALL
  SELECT d.root_path, c.path, d.depth + 1
  FROM d
  JOIN navigation_node c ON c.parent_path = d.path
)
SELECT * FROM d;

